-- M0.4 (setup wizard). Generated by drizzle-kit (step 1), with step 2 added by hand.
--
-- 1. login_attempt.action also accepts `setup`: the guesses at the one-time setup token are counted per address by the
--    same limiter as the logins, in a bucket of their own.
ALTER TABLE "login_attempt" DROP CONSTRAINT "ck_login_attempt_action";--> statement-breakpoint
ALTER TABLE "login_attempt" ADD CONSTRAINT "ck_login_attempt_action" CHECK ("login_attempt"."action" in ('login', 'mfa', 'register', 'password_lost', 'comment', 'setup'));--> statement-breakpoint
-- 2. The setup wizard's system check asks whether the latest migration is applied, as the app role. That is a read of the
--    migrator's own bookkeeping table (hashes and timestamps, no site data), which only the owner could read until now.
--    SELECT on that one table and USAGE on its schema; the app role still cannot change or create anything there.
-- The role is created by docker/postgres/init.sql. A database set up without it has nothing to grant to.
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'toascribe_app') THEN
    GRANT USAGE ON SCHEMA drizzle TO toascribe_app;
    GRANT SELECT ON TABLE drizzle.__drizzle_migrations TO toascribe_app;
  END IF;
END
$$;
